function properties(m,compact){const s=sheet(),z=M.zoneFor(s,m),contribution=m.included&&z?m.factor*z.factor:0;return `<div class="${compact?'section':''}"><h3 class="property-title">${label(m)} <span class="muted">${m.id.split('-').pop()}</span></h3><span class="pill ${m.reviewed?'ok':''}">${m.reviewed?'✓ Reviewed':'◇ Unreviewed'}</span><span class="pill ${m.included?'':'excluded'}">${m.included?'Included':'/ Excluded'}</span><p class="helper">${m.origin} origin · ${s.code}</p><div class="actions"><button class="primary" data-action="accept" ${m.reviewed?'disabled':''}>Accept</button><button data-action="${m.included?'exclude':'restore'}">${m.included?'Exclude':'Restore'}</button></div>${compact?'<button class="full" data-action="next">Next unreviewed →</button>':''}<dl class="metrics"><dt>Source factor</dt><dd>×${m.factor}</dd><dt>Allocation</dt><dd>${z?z.name:'Outside all zones'}</dd><dt>Zone factor</dt><dd>${z?'×'+z.factor:'—'}</dd><dt>Export contribution</dt><dd><strong>${contribution} items</strong></dd></dl><form data-form="classify" class="form-row"><label>Classification<select id="classify" name="category"><option value="head" ${m.category==='head'?'selected':''}>Sprinkler head</option><option value="valve" ${m.category==='valve'?'selected':''}>Isolation valve</option></select></label><button type="submit">Apply</button></form><form data-form="factor" class="form-row"><label>Items per instance<input id="factor" name="factor" type="number" min="1" max="10" step="1" value="${m.factor}" required></label><button type="submit">Apply</button></form><button class="full" data-action="cancel-draft">Cancel property edit</button><div class="section"><p>${z?`1 instance × source factor ${m.factor} × zone factor ${z.factor}${m.included?'':' × excluded'} = ${contribution} items.`:'This result is outside the outlined zones. Inclusion and allocation are separate decisions.'}</p></div></div>`;}
